// Generated by grafana-k6 on 2026-08-19T06:21:12Z
/**
 * TOEFL Prep — quiz flow smoke test.
 *
 * One VU, one iteration: login (cookie auth) -> list exams -> start an
 * attempt -> answer every item -> submit -> review -> dashboard.
 * Pure functional script: checks only, no thresholds, no load profile.
 *
 * Run:
 *   k6 run --vus 1 --iterations 1 k6/scripts/smoke-quiz-flow.js
 *
 * Prerequisites: server running (migrations + seed applied), a published
 * exam (id 1), and at least one user with email student1@toefl.dev.
 */
import http from 'k6/http';
import { check, fail } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://localhost:8080';
const API = `${BASE_URL}/api/v1`;
const EMAIL = __ENV.EMAIL || 'student1@toefl.dev';
const PASSWORD = __ENV.PASSWORD || 'student1234';
const EXAM_ID = Number(__ENV.EXAM_ID || 1);

// csrfToken extracts toefl_csrf from the login Set-Cookie header(s). k6
// sends cookies automatically on subsequent requests (VU-level jar), so we
// only need the value to echo back in the X-CSRF-Token header.
function csrfToken(loginRes) {
  const setCookie = loginRes.headers['Set-Cookie'] || '';
  const m = /toefl_csrf=([^;]+)/.exec(setCookie);
  if (!m) {
    fail('no toefl_csrf in login Set-Cookie: ' + setCookie);
  }
  return m[1];
}

function csrfHeader(token) {
  return { 'X-CSRF-Token': token, 'Content-Type': 'application/json' };
}

export const options = {};

export default function () {
  // ── Login ──────────────────────────────────────────────────────────────
  const login = http.post(
    `${API}/auth/login`,
    JSON.stringify({ email: EMAIL, password: PASSWORD }),
    { headers: { 'Content-Type': 'application/json' } },
  );
  if (!check(login, { 'login 200': (r) => r.status === 200 })) {
    fail(`login failed: ${login.status} ${login.body}`);
  }
  check(login, {
    'login user role': (r) => r.json('data.role') === 'student',
  });
  const token = csrfToken(login);

  // ── Exams ──────────────────────────────────────────────────────────────
  const exams = http.get(`${API}/exams`);
  check(exams, {
    'exams 200': (r) => r.status === 200,
    'exam id present': (r) => {
      const items = r.json('data') || [];
      return items.some((e) => e.id === EXAM_ID && e.published);
    },
  });

  // ── Start attempt ──────────────────────────────────────────────────────
  const start = http.post(
    `${API}/attempts`,
    JSON.stringify({ exam_template_id: EXAM_ID, mode: 'per_question' }),
    { headers: csrfHeader(token) },
  );
  if (!check(start, { 'start 201': (r) => r.status === 201 })) {
    fail(`start failed: ${start.status} ${start.body}`);
  }
  const attemptID = start.json('data.attempt.id');
  const items = start.json('data.items') || [];

  // ── Answer every item (correct_index is hidden; pick option 0) ─────────
  let answered = 0;
  for (const item of items) {
    const res = http.put(
      `${API}/attempts/${attemptID}/answers/${item.id}`,
      JSON.stringify({ chosen_index: 0, time_taken_ms: 1200 }),
      { headers: csrfHeader(token) },
    );
    if (check(res, { 'answer 204': (r) => r.status === 204 })) {
      answered++;
    }
  }
  check(answered, { 'all items answered': (n) => n === items.length });

  // ── Submit ─────────────────────────────────────────────────────────────
  const submit = http.post(`${API}/attempts/${attemptID}/submit`, null, {
    headers: csrfHeader(token),
  });
  check(submit, {
    'submit 200': (r) => r.status === 200,
    'report has score': (r) => typeof r.json('data.report.score_pct') === 'number',
  });

  // ── Review ─────────────────────────────────────────────────────────────
  const review = http.get(`${API}/attempts/${attemptID}/review`);
  check(review, {
    'review 200': (r) => r.status === 200,
    'review items': (r) => Array.isArray(r.json('data.items')),
  });

  // ── Dashboard ──────────────────────────────────────────────────────────
  const dashboard = http.get(`${API}/dashboard/stats`);
  check(dashboard, {
    'dashboard 200': (r) => r.status === 200,
    'dashboard total_attempts': (r) => r.json('data.total_attempts') >= 1,
  });
}